package android.content; import java.io.File; import android.hardware.input.InputManager; public class Context { public File files; public ContentResolver getContentResolver(){return new ContentResolver();} public Context getApplicationContext(){return this;} public File getFilesDir(){return files;} public <T> T getSystemService(Class<T> c){return c.cast(InputManager.INSTANCE);} public String getPackageName(){return "com.termux.x11";} }
